/**
 * Ponte entre a página e o worker do banco, e a fachada `repositorio()` que os
 * módulos usam — porte de `db/sqlite.js` + `db/repositorios.js` do legado.
 *
 * A API do repositório é deliberadamente a mesma de antes (`todos`, `obter`,
 * `contar`, `salvar`, `excluir`, `substituirTudo`): é ela que os dezessete
 * módulos vão encontrar quando forem migrados, um a um, na Fase 3.
 */

import type { Abertura, Operacao, Pedido, Registro, Resposta } from './protocolo.ts';

export type { Registro } from './protocolo.ts';

/**
 * Stores privados: o CRUD local do usuário. Nada daqui sai do aparelho — não há
 * nenhum caminho de código que os envie para a rede.
 */
export const STORES_PRIVADOS = [
  'pasta',
  'anotacao',
  'sessoes_estudo',
  'categorias_financeiro',
  'transacoes',
  'recorrencias_financeiro',
  'meta',
  'kits_checklist',
  'itens_checklist',
  'documentos_cofre',
  'estoque_alimentos',
  'relatorios_ministerio',
  'contadores_ministerio',
  'estudos_biblicos',
  'estudo_registros',
  'meu_perfil',
  'calendario_tipos',
  'calendario_eventos',
  'receitas_local',
  'guias_local',
  'poesias_local',
  'kits_local',
  'pap_caderno_estudo',
] as const;

/** Cache do conteúdo curado baixado de `dados/*.json` — somente leitura no app. */
export const STORES_CURADOS = [
  'perguntas',
  'poesias',
  'receitas',
  'guias',
  'kits',
  'criacao_modulos',
  'cronologia',
  'anotacao_modelos',
  'estoque_catalogo',
  'tutorial',
] as const;

/** O estado do armazenamento, respondido quando o banco termina de abrir. */
export interface EstadoDoBanco {
  readonly versaoSqlite: string;
  /** `false` quando o OPFS não existe e o banco caiu no despejo em IndexedDB. */
  readonly persistente: boolean;
}

/** A API de um store, igual à do legado. */
export interface Repositorio {
  todos<T extends Registro = Registro>(): Promise<T[]>;
  obter<T extends Registro = Registro>(id: number): Promise<T | undefined>;
  contar(): Promise<number>;
  /** Devolve o id gravado — o informado, ou o gerado quando o registro é novo. */
  salvar(registro: Registro): Promise<number>;
  excluir(id: number): Promise<void>;
  substituirTudo(registros: readonly Registro[]): Promise<void>;
}

let worker: Worker | undefined;
let sequencia = 0;
const pendentes = new Map<
  number,
  { resolver(valor: unknown): void; rejeitar(erro: Error): void }
>();

let aberto: Promise<EstadoDoBanco> | undefined;

function garantirWorker(): Worker {
  if (worker !== undefined) return worker;

  worker = new Worker(new URL('./worker.ts', import.meta.url), { type: 'module' });

  worker.addEventListener('error', (evento) => {
    // Falha catastrófica: nada mais vai responder, então tudo que está pendente
    // é rejeitado agora em vez de ficar esperando para sempre.
    const erro = new Error(`worker do banco falhou: ${evento.message}`);
    for (const pendente of pendentes.values()) pendente.rejeitar(erro);
    pendentes.clear();
  });

  return worker;
}

/**
 * Pede que o navegador trate este armazenamento como persistente.
 *
 * Sem isto a origem fica em "best-effort" e é a primeira candidata ao descarte
 * quando o aparelho aperta — e o que o Chrome do Android descarta é justamente
 * o OPFS e o IndexedDB, onde mora o banco, e não o `localStorage`, onde mora o
 * registro de versões da sincronização. O resultado era um app que abria vazio
 * jurando estar atualizado (ver `temConteudo` em `sincronizar.ts`).
 *
 * Num PWA instalado o Chrome concede sem perguntar. Nada aqui é obrigatório: se
 * a API não existe ou o pedido é negado, o app segue igual — só mais exposto.
 */
function pedirPersistencia(): void {
  void navigator.storage?.persist?.().catch(() => undefined);
}

/**
 * Abre o banco (uma vez por sessão) e resolve com o estado do armazenamento.
 * Chamadas seguintes recebem a mesma promessa.
 */
export function abrirBanco(): Promise<EstadoDoBanco> {
  aberto ??= new Promise<EstadoDoBanco>((resolver, rejeitar) => {
    pedirPersistencia();
    const w = garantirWorker();

    w.addEventListener('message', (evento: MessageEvent<Resposta | Abertura>) => {
      const dados = evento.data;

      if ('tipo' in dados) {
        if (dados.tipo === 'pronto') {
          resolver({ versaoSqlite: dados.versaoSqlite, persistente: dados.persistente });
        } else {
          rejeitar(new Error(dados.erro));
        }
        return;
      }

      const pendente = pendentes.get(dados.seq);
      if (pendente === undefined) return;
      pendentes.delete(dados.seq);

      if (dados.ok) {
        pendente.resolver(dados.valor);
      } else {
        pendente.rejeitar(new Error(dados.erro));
      }
    });
  });

  return aberto;
}

function operar(operacao: Operacao): Promise<unknown> {
  const w = garantirWorker();
  return new Promise((resolver, rejeitar) => {
    const seq = ++sequencia;
    pendentes.set(seq, { resolver, rejeitar });
    const pedido: Pedido = { seq, operacao };
    w.postMessage(pedido);
  });
}

/** A fachada de um store. Nenhum SQL atravessa esta fronteira. */
export function repositorio(store: string): Repositorio {
  return {
    async todos<T extends Registro = Registro>(): Promise<T[]> {
      return (await operar({ op: 'todos', store })) as T[];
    },
    async obter<T extends Registro = Registro>(id: number): Promise<T | undefined> {
      return (await operar({ op: 'obter', store, id })) as T | undefined;
    },
    async contar(): Promise<number> {
      return Number(await operar({ op: 'contar', store }));
    },
    async salvar(registro: Registro): Promise<number> {
      return Number(await operar({ op: 'salvar', store, registro }));
    },
    async excluir(id: number): Promise<void> {
      await operar({ op: 'excluir', store, id });
    },
    async substituirTudo(registros: readonly Registro[]): Promise<void> {
      await operar({ op: 'substituirTudo', store, registros });
    },
  };
}
